const KEY = 'repair-notebook-v1';
let records = [], step = 1, pending = null, savedId = null;
const say = text => { $('notice').textContent = text; };
function data(){ return Object.fromEntries(fields.map(k => [k, $(k).value.trim()])); }
function fill(d){ fields.forEach(k => { $(k).value = d[k] || (k === 'status' ? '未解决' : ''); }); }
