  const q=$('search').value.trim().toLocaleLowerCase(), host=$('history'); host.replaceChildren(); $('recordCount').textContent=records.length+' 条记录';
  const found=records.filter(r=>fields.some(k=>r[k].toLocaleLowerCase().includes(q))).slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
