function session(){ return {mode, step, data: mode === 'empty' ? blank() : data(), savedId}; }
function state(){ return {version:2, records, session:session()}; }
function paintState(){ $('draftState').textContent = ({empty:'尚未开始新记录',draft:'草稿已自动保存在本机',preview:'小结待保存到历史',saved:'本次已保存 · 无待填草稿'})[mode]; }
