function fill(d){ fields.forEach(k => { $(k).value = d[k] || (k === 'status' ? '未解决' : ''); }); }
function persist(){
  try { if(readBlocked) throw Error(); localStorage.setItem(KEY, JSON.stringify(state())); paintState(); return true; }
  catch { $('draftState').textContent = '本机保存失败 · 内容仅留在本页'; say('浏览器无法保存数据，或原有存储无法读取。请导出备份，避免关闭后丢失；下载小结不会保存维修历史。'); return false; }
}
