  for(const r of found){const box=document.createElement('details'), title=document.createElement('summary'), meta=document.createElement('small'),body=document.createElement('div'),btn=document.createElement('button');title.textContent=r.deviceId+' · '+(r.deviceName||'未命名设备')+' · '+r.status;meta.textContent='记录于 '+new Date(r.createdAt).toLocaleString('zh-CN');title.append(meta);body.className='record-body';body.append(summaryNode(r));btn.textContent='下载这条小结';btn.className='secondary';btn.addEventListener('click',()=>download(safeName(r.deviceId)+'-维修小结.txt',textSummary(r),'text/plain;charset=utf-8'));body.append(btn);box.append(title,body);host.append(box);}
}
$('repairForm').addEventListener('input',()=>{pending=null;savedId=null;mode=hasInput(data())?'draft':'empty';$('result').hidden=true;persist();});
$('repairForm').addEventListener('submit',e=>{e.preventDefault();const d=data();if(!d.deviceId||!d.incident){showStep(1);$('formError').textContent='请填写设备编号和故障经过后继续。';$(d.deviceId?'incident':'deviceId').focus();return;}if(!$('checkAt').validity.valid){showStep(3);$('formError').textContent='请填写有效的检查时间，或将它清空。';$('checkAt').focus();return;}if(step<3){showStep(step+1);persist();return;}mode=savedId?'saved':'preview';persist();preview();$('resultTitle').focus();});
