    if(s.draft && !draftValid(s.draft)) throw Error();
    const d=s.draft || blank(), match=s.records.find(r=>fields.every(k=>r[k]===d[k]));
    work=match?{mode:'saved',step:3,data:d,savedId:match.id}:{mode:hasInput(d)?'draft':'empty',step:1,data:d,savedId:null};
  }else{
    work=s.session;
    if(!work || !['empty','draft','preview','saved'].includes(work.mode) || ![1,2,3].includes(work.step) || !draftValid(work.data)) throw Error();
    if(['preview','saved'].includes(work.mode) && !valid(work.data)) throw Error();
    if(work.mode==='saved' && !s.records.some(r=>r.id===work.savedId && fields.every(k=>r[k]===work.data[k]))) throw Error();
  }
  return {records:s.records,work};
}
