    const backup=parseState(JSON.parse(await file.text())), old=records.slice();let count=0;
    for(const r of backup.records){
      if(!records.some(x=>x.createdAt===r.createdAt && fields.every(k=>x[k]===r[k]))){
        let id=r.id;while(records.some(x=>x.id===id)) id=r.id+'-'+Math.random().toString(36).slice(2);
        records.push({...Object.fromEntries(fields.map(k=>[k,r[k]])),id,createdAt:r.createdAt});count++;
      }
    }
    if(!persist()){records=old;return;}
    renderHistory();say('备份已合并，新增 '+count+' 条记录。当前填写内容保持不变。');
    if(['draft','preview'].includes(backup.work.mode)){
      const b=document.createElement('button');b.className='secondary';b.textContent='恢复备份中的未完成内容';
      b.onclick=()=>{if(!confirm('用备份中的未完成内容替换当前填写内容？'))return;$('entryCard').hidden=false;fill(backup.work.data);mode=backup.work.mode;savedId=null;pending=null;showStep(backup.work.step);$('result').hidden=true;if(mode==='preview')preview();persist();};
      $('notice').append(document.createTextNode(' 备份另有未完成内容。'),b);
    }
  }catch{say('无法导入：请选择本网页导出的有效 JSON 备份。现有记录和草稿未改变。');}finally{e.target.value='';}
};
try{
  const raw=localStorage.getItem(KEY);
  if(raw){const restored=parseState(JSON.parse(raw));records=restored.records;mode=restored.work.mode;savedId=mode==='saved'?restored.work.savedId:null;step=restored.work.step;fill(mode==='empty'?blank():restored.work.data);}
  paintState();
}catch{readBlocked=true;say('未能读取本机记录，已暂停写入以保护原数据。请导出本页内容备份；原有备份可在其他浏览器中恢复。');}
showStep(step,false);if(['preview','saved'].includes(mode))preview();renderHistory();

