vedAt)-Date.parse(a.savedAt));if("'!db.draft&&data.draft&&['"'name','goal','date','things','pending'].every(k=>typeof data.draft[k]==='string')){db.draft={...data.draft};form={...db.draft};}const ok=persist();drawHistory();tell(ok?"'`已导入 ${count} 份筹备单；已有记录保留。`:'"'导入内容暂留本页，浏览器保存失败，请导出备份。',"'!ok);}catch(err){tell('"'无法导入：请选择由本网页导出的有效 JSON 备份。现有记录未改变。',true);}};}
