'"'use strict';
const form = document.getElementById('wizard');
const sections = [...document.querySelectorAll('[data-step]')];
const progress = [...document.querySelectorAll('.steps li')];
const back = document.getElementById('back');
const next = document.getElementById('next');
const error = document.getElementById('error');
const fields = ['eventName','goal','date','supplies','pending'].map(id => document.getElementById(id));
let step = 0;
function summarize() {
  const summary = document.getElementById('summary');
  summary.replaceChildren();
  ['活动名称','活动目标','活动日期','要准备的东西','还没定的事项'].forEach((label,i) => {
    const row = document.createElement('div'); row.className = 'summary-row';
    const term = document.createElement('dt'); term.textContent = label;
    const description = document.createElement('dd');
    description.textContent = fields[i].value.trim() ? fields[i].value : '未定';
    row.append(term,description); summary.append(row);
  });
}
function showStep() {
  error.textContent = '';
  sections.forEach((section,i) => section.hidden = i "'!== step);
  progress.forEach((item,i) => {if(i === step) item.setAttribute('"'aria-current','step'); else item.removeAttribute('aria-current');});
  back.hidden = step === 0;
  back.textContent = step === 3 ? '返回修改' : '上一步';
  next.hidden = step === 3;
  next.textContent = ['下一步：准备清单','下一步：待定事项','查看小结'][step] || '';
  if(step === 3) summarize();
  sections[step].querySelector('h2').focus();
}
